#pragma once
#include <filesystem>
#include <string>
#include <vector>

// Loaded from mods/music/catalog.json (generated by tools/music_asset catalog).

struct MusicCatalogAsset
{
    std::string id;
    std::string archive;     // sonic2010_0.cpk
    std::string path;        // internal CPK path
    std::string filename;
    std::string category;    // stage / boss / menu / map / jingle / special / other
    std::string variant;     // main / fx
    std::string label;
    std::string cue;
    std::string stage;       // stg110 or empty
    std::string world;
    int act = 0;
    int fileId = 0;
    uint64_t fileSize = 0;
    int sampleRate = 0;
    int channels = 0;
    int segmentCount = 0;
    double durationSec = 0;
    bool hasLoop = false;
    float confidence = 0.f;
};

struct MusicCatalog
{
    int musicCount = 0;
    std::string archiveSha;
    std::vector<MusicCatalogAsset> assets;
};

bool MusicCatalog_Load(const std::filesystem::path& path, MusicCatalog& out, std::string& error);
std::filesystem::path MusicCatalog_DefaultPath(const std::filesystem::path& musicDir);
